"""Visible tests for check_docs.py (assignment A1). Do not edit this file: the grader runs an
unchanged copy of it against your check_docs.py. Add your own tests in a separate file.

Run: uv run python -m pytest -q -p no:cacheprovider \
         section-1-instructions/assignment/starter/checker/test_check_docs.py
"""

from __future__ import annotations

from pathlib import Path

import pytest
from check_docs import (
    Problem,
    check_links,
    check_rules,
    content_words,
    main,
    overlap,
    parse_definitions,
    slugify,
)

ORIGINAL = """# Team rules

- [R1.1] Every query on customer data filters by the caller's `org_id`.
- [R1.2] Another org's resource is answered with 404 `not_found`,
  exactly as if it did not exist.
- [R3.8] (retired 2025-03) Admin exports may use offset pagination.
- [CV-01] Prefer small pull requests that touch only the files a feature needs.
"""

GOOD_RULES = """# Security

- [R1.1] Every query on customer data filters by the caller's `org_id`.
- [R1.2] Answer another org's resource with 404 `not_found`, exactly as if it did not exist.
- [CV-01] Prefer small pull requests that touch only the files a feature needs.
"""


def write(root: Path, files: dict[str, str]) -> Path:
    for rel, text in files.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    return root


def keys(problems: list[Problem]) -> set[tuple[str, str]]:
    return {(p.kind, p.key) for p in problems}


@pytest.fixture
def product(tmp_path: Path) -> Path:
    return write(
        tmp_path / "product",
        {
            "app/api/deps.py": "",
            "tests/visible/conftest.py": "",
            "docs/features/f1.md": "# F1\n",
        },
    )


@pytest.fixture
def original(tmp_path: Path) -> Path:
    path = tmp_path / "original.md"
    path.write_text(ORIGINAL, encoding="utf-8")
    return path


# -- text helpers ---------------------------------------------------------------------------------


def test_slugify_follows_the_github_rules() -> None:
    assert slugify("R1 Tenant isolation") == "r1-tenant-isolation"
    assert slugify("Legacy /v1 API") == "legacy-v1-api"
    assert slugify("`app/api/` and **db**") == "appapi-and-db"
    assert slugify("What's new?") == "whats-new"


def test_content_words_drop_ids_stopwords_and_short_tokens() -> None:
    words = content_words("[R1.2] Another org's resource is a 404 `not_found` (see R1)")
    assert words == {"another", "org", "resource", "404", "not_found", "see"}


def test_overlap_is_the_share_of_original_words_kept() -> None:
    assert overlap("Every query filters by org_id", "Queries filter by org_id; every query") == 0.75
    assert overlap("", "anything") == 1.0


def test_parse_definitions_reads_continuations_retired_tags_and_skips_fences() -> None:
    text = (
        "# Rules\n"
        "- [R1.2] Another org's resource is a 404,\n"
        "  exactly as if it did not exist.\n"
        "- [R3.8] (retired 2025-03) Admin exports may use offset pagination.\n"
        "\n"
        "```text\n"
        "- [R9.9] not a rule\n"
        "```\n"
        "| [CV-01] | Prefer small pull requests. |\n"
    )
    defs = parse_definitions(text)
    assert [(d.rule_id, d.line, d.retired) for d in defs] == [
        ("R1.2", 2, False),
        ("R3.8", 4, True),
        ("CV-01", 9, False),
    ]
    assert "exactly as if it did not exist" in defs[0].statement
    assert "Prefer small pull requests" in defs[2].statement


# -- links ----------------------------------------------------------------------------------------


def test_a_broken_relative_link_is_reported_with_file_and_line(
    tmp_path: Path, product: Path
) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": "# Map\n\nSee [security](docs/SECURITY.md).\nSee [gone](docs/GONE.md).\n",
            "docs/SECURITY.md": "# Security\n",
        },
    )
    problems = check_links(tree, product)
    assert keys(problems) == {("broken-link", "AGENTS.md:4")}
    assert problems[0].detail == "docs/GONE.md"


def test_anchors_must_name_a_heading_in_the_target(tmp_path: Path, product: Path) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": (
                "# Map\n"
                "[r1](docs/SECURITY.md#r1-tenant-isolation)\n"
                "[r2](docs/SECURITY.md#r2-roles)\n"
                "[top](#map)\n"
            ),
            "docs/SECURITY.md": "# Security\n\n## R1 Tenant isolation\n",
        },
    )
    assert keys(check_links(tree, product)) == {("broken-anchor", "AGENTS.md:3")}


def test_fenced_code_inline_code_and_external_links_are_not_checked(
    tmp_path: Path, product: Path
) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": (
                "# Map\n"
                "```\n"
                "[x](missing.md)\n"
                "```\n"
                "Inline `[x](missing.md)` stays text.\n"
                "[site](https://example.com/a.md) and [mail](mailto:team@example.com)\n"
            ),
        },
    )
    assert check_links(tree, product) == []


def test_links_into_the_product_resolve_like_the_workspace_overlay(
    tmp_path: Path, product: Path
) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": "# Map\n[specs](docs/product-specs/index.md)\n",
            "docs/product-specs/index.md": (
                "# Specs\n[F1](../features/f1.md)\n[F9](../features/f9.md)\n"
            ),
        },
    )
    assert keys(check_links(tree, product)) == {("broken-link", "docs/product-specs/index.md:3")}


def test_code_span_paths_must_exist_and_commands_are_skipped(tmp_path: Path, product: Path) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": (
                "# Map\n"
                "Read `docs/SECURITY.md` and `app/api/deps.py`.\n"
                "Run `python -m pytest tests/visible -q`.\n"
                "See `docs/MISSING.md` and `tests/visible/`.\n"
            ),
            "docs/SECURITY.md": "# Security\n",
        },
    )
    problems = check_links(tree, product)
    assert keys(problems) == {("broken-path", "AGENTS.md:4")}
    assert problems[0].detail == "docs/MISSING.md"


# -- rules ----------------------------------------------------------------------------------------


def test_missing_and_weak_rules_are_reported(tmp_path: Path, original: Path) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": "# Map\n",
            "docs/SECURITY.md": (
                "- [R1.1] Every query on customer data filters by the caller's `org_id`.\n"
                "- [R1.2] Unrelated words entirely.\n"
            ),
        },
    )
    problems = check_rules(original, tree)
    assert keys(problems) == {("missing-rule", "CV-01"), ("weak-rule", "R1.2")}
    weak = next(p for p in problems if p.kind == "weak-rule")
    assert weak.detail.startswith("docs/SECURITY.md:2 overlap=0.")


def test_a_complete_tree_has_no_rule_problems(tmp_path: Path, original: Path) -> None:
    tree = write(tmp_path / "tree", {"AGENTS.md": "# Map\nR1 and CV-01\n", "docs/S.md": GOOD_RULES})
    assert check_rules(original, tree) == []


def test_duplicate_retired_and_unknown_ids_are_reported(tmp_path: Path, original: Path) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": "# Map\nRules R1 and R4.1 live in docs/.\n",
            "docs/A.md": GOOD_RULES,
            "docs/B.md": (
                "- [R1.1] Every query on customer data filters by the caller's `org_id`.\n"
                "- [R3.8] (retired 2025-03) Admin exports may use offset pagination.\n"
            ),
        },
    )
    assert keys(check_rules(original, tree)) == {
        ("duplicate-rule", "R1.1"),
        ("retired-rule", "R3.8"),
        ("unknown-rule", "R4.1"),
    }


def test_a_definition_in_the_map_is_reported_but_still_covers_the_rule(
    tmp_path: Path, original: Path
) -> None:
    tree = write(
        tmp_path / "tree",
        {
            "AGENTS.md": "# Map\n- [CV-01] Prefer small pull requests that touch only the files a "
            "feature needs.\n",
            "docs/S.md": GOOD_RULES.replace("- [CV-01] Prefer", "- Prefer"),
        },
    )
    assert keys(check_rules(original, tree)) == {("rule-in-map", "CV-01")}


# -- command line ---------------------------------------------------------------------------------


def test_main_prints_problems_and_exits_1_then_0_when_clean(
    tmp_path: Path, original: Path, product: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    tree = write(tmp_path / "tree", {"AGENTS.md": "# Map\n[x](docs/NONE.md)\n"})
    argv = ["--original", str(original), "--tree", str(tree), "--product", str(product)]
    assert main(argv) == 1
    out = capsys.readouterr().out.splitlines()
    assert "ERROR broken-link AGENTS.md:2 docs/NONE.md" in out
    assert "ERROR missing-rule R1.1" in out
    assert out[-1].startswith("FAILED: ")

    write(tree, {"AGENTS.md": "# Map\n[rules](docs/S.md)\n", "docs/S.md": GOOD_RULES})
    assert main(argv) == 0
    assert capsys.readouterr().out.splitlines()[-1].startswith("OK: 2 files, ")


def test_main_exits_2_when_the_tree_is_missing(tmp_path: Path, original: Path) -> None:
    assert main(["--original", str(original), "--tree", str(tmp_path / "nope")]) == 2
